function validate([ans, topRight, bottomLeft]) {
  const point = p => Array.isArray(p) && p.length === 2 && p.every(v => Number.isInteger(v) && v >= 0 && v <= 1000);
  if (!point(topRight) || !point(bottomLeft)) return 'topRight and bottomLeft are points [x, y] with 0 <= x, y <= 1000.';
  if (bottomLeft[0] > topRight[0] || bottomLeft[1] > topRight[1]) return 'bottomLeft must be below and to the left of topRight.';
  if (bottomLeft[0] === topRight[0] && bottomLeft[1] === topRight[1]) return 'topRight and bottomLeft must differ.';
  if (!Array.isArray(ans) || !ans.every(point)) return 'Each ship is a point [x, y] with 0 <= x, y <= 1000.';
  const seen = new Set(ans.map(([x, y]) => x * 1001 + y));
  if (seen.size !== ans.length) return 'Two ships cannot share a point.';
  const inside = ans.filter(([x, y]) => x >= bottomLeft[0] && x <= topRight[0] && y >= bottomLeft[1] && y <= topRight[1]).length;
  if (inside > 10) return 'The rectangle may contain at most 10 ships.';
  return null;
}

