function adapt(input, solve, kit) {
  const [ans, topRight, bottomLeft] = input;
  const ships = ans.map(([x, y]) => [x, y]);
  let calls = 0;
  // The positions stay inside this closure; the solution can only ask hasShips.
  const sea = Object.freeze({
    hasShips(corner, origin) {
      calls++;
      if (calls > 400) throw new Error('hasShips was called more than 400 times.');
      const [right, top] = corner;
      const [left, bottom] = origin;
      return ships.some(([x, y]) => x >= left && x <= right && y >= bottom && y <= top);
    },
  });
  return solve(sea, [topRight[0], topRight[1]], [bottomLeft[0], bottomLeft[1]]);
}

