function countShips(sea, topRight, bottomLeft) {
  const [right, top] = topRight;
  const [left, bottom] = bottomLeft;

  if (left > right || bottom > top) {
    return 0;
  }
  if (!sea.hasShips(topRight, bottomLeft)) {
    return 0;
  }
  if (left === right && bottom === top) {
    return 1;
  }

  const midX = Math.floor((left + right) / 2);
  const midY = Math.floor((bottom + top) / 2);

  const lowerLeft = countShips(sea, [midX, midY], [left, bottom]);
  const lowerRight = countShips(sea, [right, midY], [midX + 1, bottom]);
  const upperLeft = countShips(sea, [midX, top], [left, midY + 1]);
  const upperRight = countShips(sea, [right, top], [midX + 1, midY + 1]);
  return lowerLeft + lowerRight + upperLeft + upperRight;
}

