function countShips(sea, topRight, bottomLeft) {
  // Halve the longer side only; when the first half is empty the second must hold the ship, so it needs no call.
  const count = (x1, y1, x2, y2) => {
    if (x1 === x2 && y1 === y2) return 1;
    let first, second;
    if (x2 - x1 >= y2 - y1) {
      const m = Math.floor((x1 + x2) / 2);
      first = [x1, y1, m, y2];
      second = [m + 1, y1, x2, y2];
    } else {
      const m = Math.floor((y1 + y2) / 2);
      first = [x1, y1, x2, m];
      second = [x1, m + 1, x2, y2];
    }
    const firstHas = sea.hasShips([first[2], first[3]], [first[0], first[1]]);
    if (!firstHas) return count(...second);
    const secondHas = sea.hasShips([second[2], second[3]], [second[0], second[1]]);
    return count(...first) + (secondHas ? count(...second) : 0);
  };
  if (!sea.hasShips(topRight, bottomLeft)) return 0;
  return count(bottomLeft[0], bottomLeft[1], topRight[0], topRight[1]);
}

