function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  for (;;) {
    let bottomLeft, topRight;
    if (size === 'large') {
      bottomLeft = [pick(3), pick(3)];
      topRight = [1000 - pick(3), 1000 - pick(3)];
    } else {
      // Small: sometimes a tiny board near the origin, sometimes a board anywhere in the full range.
      const span = rand() < 0.5 ? 8 : 1000;
      const a = [pick(span + 1), pick(span + 1)], b = [pick(span + 1), pick(span + 1)];
      bottomLeft = [Math.min(a[0], b[0]), Math.min(a[1], b[1])];
      topRight = [Math.max(a[0], b[0]), Math.max(a[1], b[1])];
    }
    if (bottomLeft[0] === topRight[0] && bottomLeft[1] === topRight[1]) continue;
    const wanted = size === 'large' ? 10 : pick(11);
    const ships = [], seen = new Set();
    const add = (x, y) => { if (!seen.has(x * 1001 + y)) { seen.add(x * 1001 + y); ships.push([x, y]); return true; } return false; };
    const width = topRight[0] - bottomLeft[0] + 1, height = topRight[1] - bottomLeft[1] + 1;
    const room = Math.min(wanted, width * height);
    for (let tries = 0; ships.length < room && tries < 1000; tries++) add(bottomLeft[0] + pick(width), bottomLeft[1] + pick(height));
    // A few ships outside the rectangle, which must not be counted.
    const outside = pick(size === 'large' ? 20 : 4);
    for (let i = 0; i < outside; i++) {
      const x = pick(1001), y = pick(1001);
      if (x < bottomLeft[0] || x > topRight[0] || y < bottomLeft[1] || y > topRight[1]) add(x, y);
    }
    for (let i = ships.length - 1; i > 0; i--) { const j = pick(i + 1); [ships[i], ships[j]] = [ships[j], ships[i]]; }
    return [ships, topRight, bottomLeft];
  }
}
